button.clickEventHandler:
        const dialogId = 'ScheduleChartDialog';
        const timeline = {
          type: ESS.enums.DialogItemType.TEXT,
          name: 'timeline',
          properties: {
            text: `
              <component
                name="VacationPlanningTool"
                public-name="Directum_VacationPlanningTool_1_0"
                module-name="loaders"
                loader-name="lk-loader"
                dialog-id="${dialogId}"
              />
            `,
          },
        };

        const id = {
          type: ESS.enums.DialogItemType.INPUT,
          name: 'AssignmentId',
          properties: {
            initialValue: data.id,
            isHidden: true,
          },
        };

        const performerId = {
          type: ESS.enums.DialogItemType.INPUT,
          name: 'PerformerId',
          properties: {
            initialValue: data.performer,
            isHidden: true,
          },
        };

        const entityGuid = {
          type: ESS.enums.DialogItemType.INPUT,
          name: 'EntityGuid',
          properties: {
            initialValue: 'fb83fd0b-2a8d-43b6-8c0f-c29849fb8fc0',
            isHidden: true,
          },
        };

        const items = [
          timeline,
          id,
          performerId,
          entityGuid
        ];

        ESS.dialogs.createDialog({
          id: dialogId,
          properties: {
            width: ESS.enums.DialogWidth.WIDE,
            isFullScreen: true,
          },
          title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
          items,
        });

ESS.network.sendRequest(`/api/functions/CheckAssignmentInProcess?assignmentId=${data.id}`)
  .then(function (isAssignmentInProcess) {
    if (isAssignmentInProcess) {
      var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
      isAssignmentBlocked
        .then(message => {
          if (!message) {
            ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Complete').then(function () {
              ESS.widgets.updateWidgets();
              ESS.closeElement(sender);
            })
            .catch(function (error) {
              ESS.toasts.showErrorToastWithLog(ESS.L('HRPROSTATEMENTS.ERR_ASSIGNMENT_COMPLETION_FAILURE'), error.message);
            });
          } else {
            ESS.toasts.showToast(message, 'danger', false);
          }
        }).catch(function (err) {
          ESS.toasts.showErrorToastWithLog(err);
        });
    } else {
      ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.ASSIGNMENT_IS_ALREADY_COMPLETED'), 'danger', false);
    }
  }).catch(function (err) {
    ESS.toasts.showErrorToastWithLog(err);
  });

objectCard.openedEventHandler:
var assignmentId = data.id;
ESS.network.sendRequest(`/api/functions/GetVacationInfoFromApprovalAssignment?assignmentId=${assignmentId}`)
.then(function (vacationInfo) {
  ESS.network.sendRequest(`/api/functions/GetApprovalVacationReason?assignmentId=${assignmentId}`)
  .then(function (denyReason) {
    data.reason = denyReason;
    ESS.network.sendRequest(`/api/functions/GetInstructionApprovalAssignment?assignmentId=${data.id}`)
    .then(function (instruction) {
      ESS.network.sendRequest(`/api/functions/GetSubstituteFromAssignment?assignmentId=${data.id}`)
      .then(function (substituteInfo) {
        ESS.network.sendRequest(`/api/functions/GetNotifiableFromAssignment?assignmentId=${data.id}`)
        .then(function (notifiables) {
          configuration.content = ESS.L('@HRPROVACATIONS.COMMON_INSTRUCTION') + '<br/><br/>' + instruction + '<br/><br/>' + vacationInfo;
          if (notifiables){
            data.notifiableList = notifiables.NotifiableNames;
            data.notifiableIds = notifiables.NotifiableIds;
          }
          if (substituteInfo) {
            const substituteId = substituteInfo.SubstituteId;
            ESS.network.sendRequest(`/api/functions/GetSubstitutePositionAndJobTitle?employeeId=${substituteId}`)
            .then(function (substitutePosition) {
              data.substituteId = substituteId;
              data.substitute = substituteInfo.SubstituteName;
              resolve({configuration: configuration, data: data});
            });
          }
        });
      });
    });
  });
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, 'danger', false);
  reject();
});
